-- ScholarBridgeAi — Scholarship rewrite pass 34 (India: the IIT system and IISc)
-- Verified 2026-10-25. The structural correction matters more than any number here: the IITs are
-- NOT part of DASA (which covers NITs, IIITs, IIEST and SPAs), foreign nationals pay MORE than
-- Indian nationals at undergraduate level, and the money that exists for foreign students is a
-- monthly assistantship at postgraduate and doctoral level. Values are in INR; amount_usd_value is 0.

-- 595 IIT Kanpur — the Institute Fellowship for foreign degree students
UPDATE scholarships SET
  title = 'IIT Kanpur Institute Fellowship for Foreign Degree Students',
  description = 'IIT Kanpur states the rule in one sentence: it offers all foreign degree students a monthly fellowship at par with Indian students, and only those who do not receive any other funding are eligible for the Institute Fellowship. That is a doctoral or postgraduate research instrument, not an undergraduate award, and it is the honest centre of this record - the old one implied a USD 2,375 scholarship open to anyone. Three further routes matter and all of them run through the Government of India rather than the institute. The Study in India programme, which every foreign student must register with anyway because the registration is linked to the study visa, admits students through the PRAGATII examination, and IIT Kanpur states that meritorious students are selected for a scholarship of up to USD 3,200 to cover tuition, accommodation and mess charges. The Indian Council for Cultural Relations scholarship is applied for through the Indian embassy in the applicant country. There is also an IIT Kanpur fellowship reserved for AARDO member countries, a Doctoral Fellowship in India for ASEAN countries, and an India-Bhutan Friendship Scholarship, none of which is open to an applicant from Uzbekistan. Foreign national applicants are exempt from the application fee and from the GATE requirement, and the programmes open to them are MTech, MBA, MS by research and PhD - there is no undergraduate route.',
  requirements = 'Be a foreign national applying to an MTech, MBA, MS (Research) or PhD programme at IIT Kanpur; the foreign national category does not apply to undergraduate admission. Register on the Study in India portal, which is mandatory for all foreign students and is linked to the issue of the study visa. Submit the IIT Kanpur application through the foreign national route, where the application fee is waived and the GATE requirement does not apply. To be considered for the Institute Fellowship, hold no other funding, since the fellowship is reserved for students without another scholarship. Apply through ICCR via the Indian embassy if seeking that route, or through the Study in India / PRAGATII route for the scholarship of up to USD 3,200. The last date for online applications under the foreign national, Study in India and ICCR categories was 3 November 2026 for the current cycle.',
  coverage_type = 'Living Stipend', award_basis = 'need_based', award_amount = NULL, award_currency = 'INR', award_period = 'month',
  degree_levels = '["Master''s","PhD"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Institute fellowship plus government scholarship routes',
  tuition_coverage = 'A monthly fellowship at the same rate as Indian research students, which IIT Kanpur describes as at par rather than publishing a figure, plus the possibility of a Study in India scholarship of up to USD 3,200 covering tuition, accommodation and mess. The institute does not publish a tuition waiver for foreign nationals.',
  english_requirements = 'The award sets no separate English score; the English requirement of the chosen programme applies.',
  required_documents = '["IIT Kanpur foreign national application","Study in India portal registration","Academic transcripts and degree certificates","Statement of purpose and letters of reference","GRE or GMAT score for engineering, science or management streams where required","ICCR application number if applying through ICCR"]',
  deadline = '3 November 2026 was the last date for online applications under the foreign national, Study in India and ICCR categories for the current cycle',
  deadline_date = '2026-11-03', deadline_type = 'fixed', application_status = 'open',
  website_url = 'https://www.iitk.ac.in/oir/scholarship',
  source_url = 'https://www.iitk.ac.in/oir/how-to-apply',
  application_url = 'https://www.iitk.ac.in/doaa/pgadmission/foreign-students.php',
  verification_status = 'verified', source_reliability = 8, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from IIT Kanpur own pages read on 2026-10-25: iitk.ac.in/oir/scholarship states that IIT Kanpur offers all foreign degree students a monthly fellowship at par with Indian students and that only students who do not receive any other funding are eligible for the Institute Fellowship, and lists the India-Bhutan Friendship Scholarship at INR 35,000 a month for Bhutanese MTech students; iitk.ac.in/oir/how-to-apply lists the routes as ICCR, Study in India, the IIT Kanpur fellowship to AARDO member countries, the Doctoral Fellowship in India for ASEAN, the India-Bhutan Friendship Scholarship and the Institute Fellowship, and states that Study in India students may sit the PRAGATII examination with meritorious students selected for a scholarship of up to USD 3,200 covering tuition, accommodation and mess; iitk.ac.in/doaa/pgadmission/foreign-students.php and the PG admissions page confirm that the application fee is waived for the foreign national category, that the GATE requirement is waived, that registration on the Study in India portal is mandatory and linked to the study visa, and that the last date for online applications was 3 November 2026. CORRECTIONS: the row was titled IIT Kanpur Scholarships, carried an invented USD 2,375, listed all three degree levels and gave a varies-January-March deadline. There is no undergraduate foreign national route at IIT Kanpur and no scholarship of that size; the real instrument is a monthly doctoral or postgraduate fellowship at Indian-student rates plus government scholarship routes. amount_usd_value is 0 because no rupee figure is published by the institute and award_amount is left NULL rather than converting the national stipend rate into an IIT Kanpur promise.'
WHERE id = 595;

-- 596 IIT Kharagpur — retired: no institute-funded award published for international students
UPDATE scholarships SET
  title = 'IIT Kharagpur - no institute-funded scholarship published for international students (retired)',
  description = 'IIT Kharagpur publishes its scholarship and assistantship pages around Indian students: the institute scholarship is awarded merit-cum-means to students of the four-year BTech, five-year dual degree, five-year BArch and integrated MSc programmes, and the assistantship tables give the research stipend for doctoral scholars. What is not published anywhere on those pages is a scholarship for foreign nationals funded by the institute. International students reach IIT Kharagpur through the Government of India schemes - the Indian Council for Cultural Relations scholarship, the Study in India programme and the Doctoral Fellowship in India for ASEAN - and each of those is a national scheme with its own record rather than an IIT Kharagpur award. The old record claimed a USD 2,375 IIT Kharagpur Scholarship with a varies January to March deadline; no such award is published, so the row is withdrawn rather than left standing with an authoritative-looking figure.',
  coverage_type = 'Unspecified', award_basis = 'variable', award_amount = NULL, award_currency = 'INR', amount_usd_value = 0,
  deadline = 'Not published', deadline_date = NULL, deadline_type = 'not_published',
  website_url = 'https://www.iitkgp.ac.in/scholarships',
  source_url = 'https://www.iitkgp.ac.in/scholarships',
  verification_status = 'verified', source_reliability = 8, is_active = false,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Retired after reading the IIT Kharagpur scholarships and assistantships pages on 2026-10-25: iitkgp.ac.in/scholarships describes only institute scholarships awarded merit-cum-means to Indian programme students, and iitkgp.ac.in/assistantships gives the doctoral fellowship rates, neither of which addresses foreign nationals or publishes an international scholarship. The former row carried an invented USD 2,375 and a varies January to March deadline. Foreign nationals do reach IIT Kharagpur through ICCR, Study in India and the ASEAN doctoral fellowship, all of which are Government of India schemes that belong in their own records, so nothing was invented to fill the gap. The row is deactivated and the source page is kept so the claim can be checked.'
WHERE id = 596;

-- 597 IIT Madras — honest partial: the GE scholarship route exists but publishes no value
UPDATE scholarships SET
  title = 'IIT Madras International Admissions (Global Engagement Scholarship and ICCR routes)',
  description = 'IIT Madras is the clearest of the IITs about how international students actually fund a place, and the answer is uncomfortable: the Office of Global Engagement states that many international students apply through the Indian Council for Cultural Relations and the Study in India programmes, that roughly 10% of applicants receive an offer letter, and that only about 20% of those offered are awarded a scholarship and enrol. The rest cannot afford it, because foreign nationals at IIT Madras pay a much higher fee structure than Indian students - the 2026 fee circular puts the foreign national BTech entry payment at about INR 5,68,000 with tuition of INR 5,00,000 a semester, against nil tuition for SC and ST Indian students and INR 1,00,000 a semester for general Indian students. The institute lists two funding routes for international applicants on its Global Engagement pages: the ICCR scholarship, applied for through the ICCR A2A portal and quoted as the application number on the IIT Madras application, and an IIT-M GE Scholarship scheme that the pages name but do not describe, with no value, no eligibility detail and no deadline published. Research applicants also have the IITM-AARDO fellowship, which is limited to AARDO member countries, and the ASEAN doctoral fellowship, neither of which is open to Uzbekistan. A separate alumni-funded Ravishankar G International Student Scholarship has been proposed to pay living allowances at the half-time teaching or research assistantship rate of about INR 10 lakh per student over two years, but it is a fundraising proposal rather than an open competition.',
  requirements = 'Be a foreign national applying to an MTech, MS by research or PhD programme at IIT Madras through the Global Engagement international admissions portal. Upload academic records, a research statement and the required documents to that portal. Apply separately on the ICCR A2A scholarship portal if you are seeking ICCR funding, and quote the ICCR application number in the IIT Madras application. Register on the Study in India portal, which is mandatory for foreign students. Note that the institute publishes no eligibility criteria, value or deadline for the IIT-M GE Scholarship scheme, so confirm directly with the Office of Global Engagement before relying on it. Expect to pay the foreign national fee structure unless a scholarship is awarded, since IIT Madras does not publish a general tuition waiver for foreign nationals.',
  coverage_type = 'Unspecified', award_basis = 'need_based', award_amount = NULL, award_currency = 'INR', award_period = 'variable',
  degree_levels = '["Master''s","PhD"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Government scholarship routes plus an institute scheme without published terms',
  tuition_coverage = 'No value published. The ICCR route funds tuition and living costs under the Government of India scheme; the IIT-M GE Scholarship scheme is named but not described; the IITM-AARDO fellowship and the ASEAN doctoral fellowship are restricted to those member countries. Foreign national tuition otherwise applies at the higher international rate.',
  english_requirements = 'The routes set no separate English score on the IIT Madras pages; the English requirement of the chosen programme applies, and engineering, science and management applicants are asked for GRE or GMAT where applicable.',
  required_documents = '["IIT Madras Global Engagement international admission application","Academic records and research statement","GRE or GMAT score where required","Study in India portal registration","ICCR A2A application number if applying through ICCR","Letters of reference"]',
  deadline = 'Not published for the IIT-M GE Scholarship scheme; IIT Madras runs its international research admission cycles and advises applying through the Global Engagement portal',
  deadline_date = NULL, deadline_type = 'not_published', application_status = 'unknown',
  expected_deadline_period = 'IIT Madras publishes research admission rounds by semester rather than a single scholarship date; the scheme named on its Global Engagement page carries no published deadline.',
  website_url = 'https://ge.iitm.ac.in/programs/student-inbound/scholarships',
  source_url = 'https://ge.iitm.ac.in/programs/student-inbound/mtech',
  application_url = 'https://admissions.ge.iitm.ac.in/',
  verification_status = 'verified', source_reliability = 7, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from IIT Madras own pages read on 2026-10-25: ge.iitm.ac.in/programs/student-inbound/mtech states that international applicants apply through the Global Engagement international admissions portal and that scholarship schemes include ICCR and the IIT-M GE Scholarship scheme; ge.iitm.ac.in/programs/student-inbound/ms-phd states that applicants must apply through the international portal and provide the ICCR application number where relevant; ge.iitm.ac.in/programs/student-inbound/scholarships lists AARDO as a route for MS by research; the IIT Madras research admission brochure for foreign nationals lists the categories as self-finance, ICCR, embassy and foreign government scholarships, Study in India, the IIT system portal, the ASEAN scholarship and MoU partner admission; the alumni Joy of Giving page explains that about 10% of international applicants receive an offer and only about 20% of those are funded, at a proposed living allowance at the half-time teaching or research assistantship rate of about INR 10 lakh per student over two years; the 2026 fee circular published at fees.iitm.ac.in puts the foreign national BTech first payment at about INR 5,68,000 with tuition of INR 5,00,000 a semester. CORRECTIONS: the row was titled IIT Madras Scholarships, carried an invented USD 2,375, listed all three degree levels and gave a varies January to March deadline. IIT Madras publishes no institute-funded international scholarship with a value, so amount_usd_value is 0 and award_amount is NULL, the coverage type is Unspecified because nothing is quantified, and the record now says plainly that the named GE scheme has no published terms and that the foreign national fee is far above the Indian one. coverage_type was deliberately not set to a funded label.'
WHERE id = 597;

-- 598 IIT Bombay — the Foreign National Teaching Assistantship, and the warning about FRN-SF
UPDATE scholarships SET
  title = 'IIT Bombay Foreign National Teaching Assistantship (Ph.D.)',
  description = 'IIT Bombay splits foreign doctoral applicants into two categories that look similar on the application form and behave nothing alike. Under the Foreign National Teaching Assistantship category a doctoral student receives a monthly assistantship for a maximum of five years or until the thesis is submitted, whichever comes first, and the institute brochure for foreign nationals gives the rate as INR 31,000 a month for the first two years and INR 35,000 for the remaining period. Under the self-financed foreign national category, labelled FRN-SF, the institute states plainly that there is no assistantship at all. The doctorate assistantship table on the current academics site shows the Ministry of Education teaching assistantship rates of INR 37,000 for the first two years and INR 42,000 thereafter, which is the rate an Indian full-time doctoral student receives, so the assistantship attached to the foreign national category should be confirmed with the academic office at the point of offer rather than assumed. Admission under the assistantship category runs twice a year, with applications for the autumn semester closing on 31 March and offers by 31 May. The other route is the Indian Council for Cultural Relations award, applied for through the Indian embassy, and the Doctoral Fellowship in India for ASEAN, which is limited to ASEAN countries and does not apply to Uzbekistan.',
  requirements = 'Be a foreign national applying to a PhD programme at IIT Bombay and choose the Foreign National Teaching Assistantship category rather than the self-financed FRN-SF category, because the self-financed route carries no institute assistantship. Submit the application through the IIT Bombay international admissions portal with a statement of purpose for each academic unit, and at most two disciplines may be chosen. Pay the non-refundable application fee where the assistantship category requires it. Provide the qualifying degree and meet the teaching obligation of about eight hours a week, since continuation of the assistantship depends on serving as a teaching assistant and on satisfactory academic performance. Apply by 31 March for autumn semester admission or by 14 August for spring semester. Applicants who are employed are not eligible under the teaching assistantship category, and applicants from ASEAN countries should also consider the Doctoral Fellowship in India for ASEAN.',
  coverage_type = 'Living Stipend', award_basis = 'fixed', award_amount = 31000, award_currency = 'INR', award_period = 'month',
  degree_levels = '["PhD"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Institute teaching assistantship',
  tuition_coverage = 'A monthly assistantship rather than a tuition waiver: INR 31,000 a month for the first two years and INR 35,000 thereafter according to the brochure for foreign nationals, payable for up to five years or until thesis submission. The current doctorate assistantship table shows the Ministry of Education rates of INR 37,000 and INR 42,000, so the applicable rate should be confirmed at the point of offer. The self-financed foreign national category receives nothing.',
  english_requirements = 'The assistantship sets no separate English score; the English requirement of the doctoral programme applies.',
  required_documents = '["IIT Bombay international admission application","Statement of purpose for each academic unit","Qualifying degree certificates and transcripts","Application fee payment where the assistantship category requires it","Letters of recommendation"]',
  deadline = '31 March for autumn semester admission and 14 August for spring semester admission',
  deadline_date = NULL, deadline_type = 'annual', application_status = 'open',
  expected_deadline_period = 'Autumn semester applications close on 31 March each year with offers by 31 May; spring semester applications close on 14 August.',
  website_url = 'https://acad.iitb.ac.in/admissions/research',
  source_url = 'https://acad.iitb.ac.in/admissions/research',
  application_url = 'https://portal.iitb.ac.in/intadm/login',
  verification_status = 'verified', source_reliability = 8, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from IIT Bombay own pages read on 2026-10-25: acad.iitb.ac.in/admissions/research gives the admissions category table with the teaching assistantship at INR 37,000 for the first two years and INR 42,000 thereafter, the research assistantship at INR 42,000 and INR 47,000, the note that self-financed foreign nationals under FRN-SF receive no assistantship from IIT Bombay, and the ICCR category with assistance from ICCR; the IIT Bombay information brochure for foreign nationals states that foreign nationals may apply under the Foreign Teaching Assistantship FRN-TA category, that the assistantship lasts a maximum of five years or until thesis submission, that the monthly rate is INR 31,000 for the first two years and INR 35,000 for the remaining period, that applications close on 15 February and 14 August in the older edition and that admission for foreign nationals is made twice a year with the autumn application deadline of 31 March and offers by 31 May, and that the Doctoral Fellowship in India for ASEAN covers ASEAN scholars only. The two published rates conflict, which is recorded in the description and in this note rather than resolved by choosing the flattering one. CORRECTIONS: the row was titled IITB Scholarship for International Students, carried an invented USD 9,000, listed all three degree levels and gave a varies January to March deadline. There is no IITB scholarship by that name; the real instrument is a doctoral teaching assistantship, and the record now warns that the self-financed category receives nothing. amount_usd_value is 0 because the provider publishes in rupees and award_amount carries the brochure rate of INR 31,000 a month.'
WHERE id = 598;

-- 599 IIT Delhi — foreign PhD teaching assistantship, IoE fellowships, and a masters scholarship
UPDATE scholarships SET
  title = 'IIT Delhi Assistantships and Fellowships for Foreign Nationals',
  description = 'IIT Delhi is the most generous of the IITs to foreign students on paper and the terms are specific. All full-time foreign nationals admitted to a PhD programme are awarded a teaching assistantship of INR 37,000 a month for the first two years and INR 42,000 a month for the following three. Foreign nationals in MTech, MDes or MS by research are eligible to be considered for a limited number of merit-based teaching assistantships of INR 12,400 a month. Fellowships under the Institution of Eminence scheme are available to foreign PhD research scholars at the same rate as Indian PhD scholars, and a limited number of International Masters Scholarships exist for international MTech, MDes and MS by research students who have not qualified GATE or CEED, selected by a central committee on the recommendation of the academic unit. The fee position is the part that usually surprises applicants in a good way: foreign students admitted to postgraduate and doctoral programmes are charged fees at par with Indian students, not the higher undergraduate foreign national rate. The undergraduate side runs the other way - the fee circular for the 2025 entry BTech and dual degree students sets foreign national tuition at USD 1,000 a semester for SAARC countries and USD 2,000 a semester for non-SAARC countries, plus about INR 31,000 of other charges, so an applicant from Uzbekistan pays rather than receives at that level.',
  requirements = 'Be a foreign national applying to a PhD, MTech, MDes or MS by research programme at IIT Delhi; the entrance examination requirement of GATE, JAM or CEED is waived for foreign nationals, though applicants who took their qualifying degree in India must still meet the national examination requirement. Apply through the IIT Delhi admission portal for foreign nationals by the published deadline for the semester, which for the second semester of 2026-27 was 29 October 2026. Hold a valid qualifying degree, with an OCI or PIO card treated as a separate category. For the PhD teaching assistantship no separate application is needed beyond admission as a full-time foreign national. For the International Masters Scholarship, be an international MTech, MDes or MS by research student who has not qualified GATE or CEED, since selection is made centrally from the academic unit recommendations. PhD applicants may also apply through ICCR via the Indian embassy.',
  coverage_type = 'Living Stipend', award_basis = 'fixed', award_amount = 37000, award_currency = 'INR', award_period = 'month',
  degree_levels = '["Master''s","PhD"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Teaching assistantship and institute fellowship',
  tuition_coverage = 'A monthly assistantship rather than a tuition waiver: INR 37,000 for the first two years and INR 42,000 for the next three at PhD level, and INR 12,400 a month for a limited number of MTech, MDes and MS by research students. Postgraduate and doctoral foreign students pay the same fees as Indian students.',
  english_requirements = 'The assistantships set no separate English score; the English requirement of the chosen programme applies.',
  required_documents = '["IIT Delhi foreign national admission application","Qualifying degree certificates and transcripts","Statement of purpose and letters of recommendation","GATE, JAM or CEED score where the applicant already holds one","ICCR application number if applying through ICCR"]',
  deadline = 'The foreign national portal for the second semester of 2026-27 closed on 29 October 2026; each semester runs its own window',
  deadline_date = NULL, deadline_type = 'annual', application_status = 'open',
  expected_deadline_period = 'IIT Delhi opens a foreign national portal for each semester, with the most recent published deadline of 29 October 2026 for the second semester of 2026-27.',
  website_url = 'https://international.iitd.ac.in/78-2/',
  source_url = 'https://international.iitd.ac.in/78-2/',
  application_url = 'https://academics.iitd.ac.in/pg-admissions/',
  verification_status = 'verified', source_reliability = 8, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from IIT Delhi own pages read on 2026-10-25: international.iitd.ac.in/78-2 states that all full-time foreign nationals admitted to the PhD programme are awarded a teaching assistantship of INR 37,000 a month for the first two years and INR 42,000 a month for the next three, and that foreign nationals pursuing MTech, MDes or MS(R) are eligible for a limited number of merit-based teaching assistantships of INR 12,400 a month; intladm.iitd.ac.in/eligibility-criteria states that Institution of Eminence fellowships are available to foreign PhD research scholars at the same rate as Indian PhD scholars, that some MTech, MDes and MS(R) students may be considered for assistantship, and that the fees of foreign students admitted to postgraduate and doctoral programmes are at par with Indian students; academics.iitd.ac.in/postgraduate-academic-rules describes the International Masters Scholarship Programme as a limited number of scholarships for international MTech, MDes and MS(R) students who have not qualified GATE or CEED, selected centrally on academic unit recommendations; academics.iitd.ac.in/pg-admissions and home.iitd.ac.in/pg-admissions give the foreign national portal and the 29 October 2026 deadline for the second semester of 2026-27; the 2025-26 entry fee structure PDF sets foreign student undergraduate tuition at USD 1,000 a semester for SAARC countries and USD 2,000 for non-SAARC countries plus INR 31,000 of other charges and institute residence fee. CORRECTIONS: the row was titled IITD Scholarship for International Students, carried an invented USD 9,000, listed all three degree levels and gave a varies January to March deadline. There is no award of that name or size; the real money is a doctoral teaching assistantship, the postgraduate fee is at par with Indian students, and the undergraduate foreign national fee is a payment rather than a scholarship. amount_usd_value is 0 because the provider publishes in rupees and award_amount carries the published INR 37,000 monthly rate.'
WHERE id = 599;

-- 601 Indian Institute of Science — the international research fellowship
UPDATE scholarships SET
  title = 'IISc Fellowship for Full-time International Research Students',
  description = 'This is the cleanest international funding offer in the Indian cluster and it is genuinely worth planning around. IISc admits foreign nationals who do not hold Overseas Citizenship of India through a dedicated international research route with no application fee, and if selected the institute offers hostel accommodation on campus and a fellowship equal to what an Indian student receives - which IISc describes as usually adequate to pay tuition fees, hostel and mess fees and cover living expenses. The rates are published: PhD scholars receive INR 37,000 a month for the first two years and INR 42,000 a month from the third year to the end of the fifth, subject to passing the comprehensive examination, and MTech by research scholars receive INR 12,400 a month. The programmes open to international applicants are a PhD in Science and Engineering and an MTech by research in Engineering; the integrated PhD is explicitly closed to them. IISc also runs an international route into its MTech and MDes coursework programmes, whose admitted students receive the same INR 12,400 a month, with the application window for the 2026-27 academic year running from 11 February to 23 March 2026. Beyond the institute fellowship there are merit-based donor fellowships that can raise the monthly amount to as much as double for coursework and research students.',
  requirements = 'Be a foreign national not holding Overseas Citizenship of India; holders of an Indian passport apply through the regular admission process, and OCI cardholders are treated as foreign nationals only in defined categories. Apply online through the IISc international admissions portal, where there is no application fee, and choose up to three departments or centres. Apply for a PhD in Science and Engineering or an MTech by research in Engineering; the integrated PhD is not open to foreign nationals. Provide a strong academic record, a qualifying bachelor degree from outside India for the research programmes, and standardised scores such as GATE or GRE where available, since IISc values them in selection. Complete the comprehensive examination to move from the INR 37,000 to the INR 42,000 doctoral rate. The MTech and MDes coursework route runs a separate window, which for the 2026-27 academic year was 11 February to 23 March 2026.',
  coverage_type = 'Full Funding', award_basis = 'fixed', award_amount = 37000, award_currency = 'INR', award_period = 'month',
  degree_levels = '["Master''s","PhD"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Institute fellowship with hostel accommodation',
  tuition_coverage = 'A monthly fellowship equal to the Indian-student rate plus hostel accommodation, which IISc states is usually adequate to cover tuition, hostel and mess fees and living expenses: INR 37,000 a month for the first two years and INR 42,000 from year three to year five at PhD level, and INR 12,400 a month for MTech by research and coursework students.',
  english_requirements = 'The fellowship sets no separate English score; the English requirement of the chosen programme applies, and standardised scores such as GATE or GRE strengthen the application.',
  required_documents = '["IISc international admissions online application","Academic transcripts and degree certificates from outside India","Statement of purpose and letters of recommendation","GATE or GRE score where available","No application fee"]',
  deadline = 'The research admission cycle runs for the August session; the MTech and MDes coursework window for 2026-27 was 11 February to 23 March 2026',
  deadline_date = NULL, deadline_type = 'annual', application_status = 'open',
  expected_deadline_period = 'IISc runs its international research admission for the August session each year with offers typically by the end of April, and a separate coursework window in February and March.',
  website_url = 'https://oir.iisc.ac.in/index.php/iisc-full-time-international-research-programmes/',
  source_url = 'https://oir.iisc.ac.in/index.php/iisc-full-time-international-research-programmes/',
  application_url = 'https://oir.iisc.ac.in/index.php/research-program-admission/',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from IISc own pages read on 2026-10-25: oir.iisc.ac.in/index.php/iisc-full-time-international-research-programmes states that the mechanism is for foreign nationals not holding Overseas Citizenship of India, that applications are online only with no application fee, that each applicant may choose up to three departments or centres, that successful candidates are offered hostel accommodation and a fellowship by IISc equal to that offered to Indian students which is usually adequate to pay tuition, hostel and mess fees and living expenses, that foreign students may apply for a PhD in Science and Engineering or an MTech by research in Engineering, and that they are not eligible for the integrated PhD; oir.iisc.ac.in research and MTech admission pages and the FAQs give the stipend rates of INR 37,000 for the first two years and INR 42,000 from the third to the fifth year for PhD, INR 12,400 a month for MTech by research and for MTech and MDes coursework students, and the 11 February to 23 March 2026 application window for the 2026-27 coursework intake; iisc.ac.in/admissions/fees-and-scholarships confirms the same stipend table and notes that IISc has merit-based private and donor fellowships that can provide enhanced monthly fellowship up to two times. CORRECTIONS: the row was titled Indian Institute of Science Fellowships, carried an invented USD 2,375, listed all three degree levels and gave a varies January to March deadline. The award is a monthly institute fellowship at Indian-student rates, it is open at doctoral and research masters level only, and it includes hostel accommodation; there is no undergraduate route. amount_usd_value is 0 because the provider publishes in rupees and award_amount carries the published INR 37,000 monthly doctoral rate.'
WHERE id = 601;

-- university_scholarships cards
UPDATE university_scholarships u SET scholarship_name = v.name, availability_status = v.avail, funding_type = v.ftype, max_scholarship = v.mx, covers_tuition = v.tuition, covers_living_expenses = v.living, eligibility_notes = v.elig, official_url = v.url, source_url = v.url, verification_status = 'verified', last_verified_at = now()
FROM (VALUES
  (293, 'IIT Kanpur Institute Fellowship for Foreign Degree Students', 'Yes', 'Institute fellowship at Indian-student rates plus government scholarship routes', 'Monthly fellowship at par with Indian research students, no published rupee figure; Study in India scholarship up to USD 3,200', true, true, 'Postgraduate and doctoral only: MTech, MBA, MS by research and PhD. Application fee and GATE waived. Institute Fellowship reserved for students with no other funding. Study in India registration is mandatory and linked to the study visa. 3 November 2026 was the last date for the current cycle.', 'https://www.iitk.ac.in/oir/scholarship'),
  (288, 'IIT Madras International Admissions (Global Engagement Scholarship and ICCR routes)', 'Yes', 'Government scholarship routes plus an institute scheme without published terms', 'No value published', false, false, 'The ICCR route funds tuition and living costs and is applied for via the ICCR A2A portal. The IIT-M GE Scholarship scheme is named but publishes no value, criteria or deadline. AARDO and ASEAN fellowships are restricted to those countries. Foreign nationals otherwise pay the higher international fee.', 'https://ge.iitm.ac.in/programs/student-inbound/scholarships'),
  (169, 'IIT Bombay Foreign National Teaching Assistantship (Ph.D.)', 'Yes', 'Institute teaching assistantship', 'INR 31,000 a month for two years then INR 35,000, up to five years', false, true, 'Doctoral only, and only under the Foreign National Teaching Assistantship category: the self-financed FRN-SF category receives no assistantship. Apply by 31 March for autumn or 14 August for spring. ASEAN applicants may also use the Doctoral Fellowship in India for ASEAN.', 'https://acad.iitb.ac.in/admissions/research'),
  (105, 'IIT Delhi Assistantships and Fellowships for Foreign Nationals', 'Yes', 'Teaching assistantship and institute fellowship', 'INR 37,000 a month for two years then INR 42,000 for three, at PhD level', true, true, 'All full-time foreign PhD students receive the teaching assistantship; MTech, MDes and MS(R) students may receive INR 12,400 a month. Postgraduate and doctoral foreign students pay the same fees as Indian students. Entrance exams waived for foreign nationals.', 'https://international.iitd.ac.in/78-2/'),
  (286, 'IISc Fellowship for Full-time International Research Students', 'Yes', 'Institute fellowship with hostel accommodation', 'INR 37,000 a month rising to INR 42,000, plus hostel accommodation', true, true, 'Foreign nationals without OCI cards only, PhD in Science and Engineering or MTech by research in Engineering; the integrated PhD is closed. No application fee. Fellowship is equal to the Indian-student rate and usually covers tuition, hostel, mess and living costs.', 'https://oir.iisc.ac.in/index.php/iisc-full-time-international-research-programmes/'),
  (287, 'IIT Kharagpur - no institute-funded scholarship published for international students', 'No', 'Not applicable', 'None published for international students', false, false, 'IIT Kharagpur publishes institute scholarships for Indian programme students and doctoral assistantship rates, but no institute-funded award for foreign nationals. International applicants reach the institute through ICCR, Study in India and the ASEAN doctoral fellowship, which are Government of India schemes.', 'https://www.iitkgp.ac.in/scholarships')
) AS v(id, name, avail, ftype, mx, tuition, living, elig, url)
WHERE u.id = v.id;
